/**
 * Initialize a new hank with basic template files
 */
export async function initProject(targetDir: string): Promise<void> {
  // Ensure target directory exists
  if (!fs.existsSync(targetDir)) {
    fs.mkdirSync(targetDir, { recursive: true });
  }

  // Check if directory is empty or only has .git
  const existingFiles = fs.readdirSync(targetDir);

  if (existingFiles.length > 0) {
    throw new Error(
      `Directory ${targetDir} is not empty. Please run init in an empty directory or specify a new directory.`,
    );
  }

  // Create prompts directory
  const promptsDir = path.join(targetDir, "prompts");
  fs.mkdirSync(promptsDir, { recursive: true });

  // Create data directory
  const dataDir = path.join(targetDir, "data");
  fs.mkdirSync(dataDir, { recursive: true });

  // Write template files from inlined content
  for (const [targetPath, content] of Object.entries(templates)) {
    const fullPath = path.join(targetDir, targetPath);
    const dir = path.dirname(fullPath);

    // Ensure parent directory exists
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    fs.writeFileSync(fullPath, content, "utf-8");
  }

  console.log(`\n✅ Initialized hank in ${targetDir}\n`);
  console.log("Created files:");
  console.log("  - hank.json");
  console.log("  - prompts/analyze-haiku.md");
  console.log("  - prompts/analyze-gemini.md");
  console.log("  - prompts/analyze-pi.md");
  console.log("  - prompts/analyze-gpt.md");
  console.log("  - data/sample1.txt");
  console.log("  - data/sample2.txt");
  console.log("  - data/notes.txt");
  console.log("  - README.md");
  console.log("  - .gitignore");
}
